// `zengine::graphics` alone, as a stranger links it: an owner's picture coloured by the pool's
// names and by slots of its own, generated by the installed zengine_names(); the shipped palettes;
// a node painted for light by the installed painter, handed its colours, read back and pressed; and
// the terminal's ink, size and copy sequence from the installed claim -- with no other Zengine
// target on the link line, so a graphics header that needs another package stops this compiling.

#include "graphics/canvas.hpp"
#include "graphics/colors.hpp"
#include "graphics/implied.hpp"
#include "graphics/light_paint.hpp"
#include "graphics/ops.hpp"
#include "graphics/themes.hpp"
#include "graphics/vocabulary.hpp"
#include "graphics/window/terminal_io.hpp"
#include "kitchen/colors.hpp" // generated from stranger_slots.json by the installed zengine_names()

#include <cstdio>
#include <cstdlib>
#include <string>

namespace {

void check(bool ok, const char* what) {
    std::printf("  %s %s\n", ok ? "ok  " : "FAIL", what);
    if (!ok) {
        std::exit(1);
    }
}

} // namespace

int main() {
    namespace gfx = zengine::graphics;
    std::printf("zengine::graphics alone, as an installed package sees it\n");

    gfx::Sketch picture;
    picture.fill_rect("plate", 0, 0, 48, 24, kitchen::colors::plate);
    picture.text("label", 4, 6, "soup", gfx::colors::accent);
    const auto plate_args = gfx::from_body<gfx::RectArgs>(picture.nodes()[0].args);
    const auto label_args = gfx::from_body<gfx::TextArgs>(picture.nodes()[1].args);
    check(plate_args && plate_args->fill.from == gfx::color_from::kSlot &&
              plate_args->fill.name == "plate" && plate_args->fill.rgba == 0x336699ff &&
              plate_args->fill.like == "background",
          "a slot of the pane's own is its name, its default and the pool colour it is like");
    check(label_args && label_args->ink.from == gfx::color_from::kPool &&
              label_args->ink.name == "accent",
          "a pool colour is its name, which the window turns into a colour");

    const gfx::PaletteOffered day = gfx::themes::day();
    check(day.palette == "day" && !day.colors.empty() && gfx::themes::shipped().size() == 4,
          "the shipped themes come with the package as palettes");

    gfx::PaintTask task;
    task.nodes.push_back(gfx::PaintNode{"plate", {1}, picture.nodes()[0].op,
                                        picture.nodes()[0].args,
                                        {gfx::PaintInk{0x336699ff, {}, {}}, gfx::PaintInk{}}});
    task.nodes.push_back(gfx::PaintNode{"label", {2}, picture.nodes()[1].op,
                                        picture.nodes()[1].args,
                                        {gfx::PaintInk{0x112233ff, {}, {}}}});
    const gfx::PaintResult painted = gfx::light::paint_task(task);
    check(painted.nodes.size() == 2, "the painter for light paints each node");
    const auto plate = gfx::light::unpack_node(painted.nodes[0].cells);
    const auto label = gfx::light::unpack_node(painted.nodes[1].cells);
    check(plate && plate->quads.size() == 1 && plate->quads[0].w == 48 &&
              plate->quads[0].rgba == 0x336699ffu,
          "a rectangle is one quad, in the area's pixels, in the colour it was handed");
    check(label && label->texts.size() == 1 && label->texts[0].text == "soup" &&
              label->texts[0].rgba == 0x112233ffu,
          "a text is one run, in the colour it was handed");
    const gfx::TextMeasure face{8, 18};
    check(gfx::light::hits_node(*plate, 10, 10, face) &&
              !gfx::light::hits_node(*plate, 60, 10, face),
          "a point lands on what was painted, and nowhere else");
    check(gfx::light::hits_node(*label, label->texts[0].x + 4 * face.advance - 1,
                                label->texts[0].y, face) &&
              !gfx::light::hits_node(*label, label->texts[0].x + 4 * face.advance,
                                     label->texts[0].y, face),
          "a run of text is pressed over its characters, a character an advance of the face");
    check(!gfx::light::unpack_node(loom::Bytes{1, 2, 3}).has_value(),
          "bytes a character painter wrote are not read as light");

    check(gfx::window::sgr_for("cyan", 0) == "\x1b[36m" &&
              gfx::window::sgr_for("", 0xff0000ff) == "\x1b[91m",
          "the terminal's ink for a colour, its word or its nearest, comes with the package");
    const gfx::window::TerminalSize size = gfx::window::native_terminal_size();
    check(size.cols >= 0 && size.rows >= 0, "a terminal's size is asked, and never negative");
    check(gfx::window::terminal_clipboard_sequence("soup") == "\x1b]52;c;c291cA==\x07",
          "a copy is the terminal's OSC 52 sequence, its text in base64");
    return 0;
}
